<?php

namespace App\Medical\Documents;

use App\Medical\Ai\Work\WorkDir;
use Symfony\Component\Process\Exception\ProcessTimedOutException;
use Symfony\Component\Process\Process;

/**
 * The only code that runs pdfinfo/pdftoppm. Every spawn is an argv array behind a virtual memory limit with a hard timeout;
 * only paths generated by the app are passed, and nothing the tools print is kept.
 */
final class PdfRasterizer
{
    /** @param  string  $profile  'web' (the app container) or 'worker' (the ai-worker): picks the memory limit. */
    public function pageCount(string $absPdf, string $profile = 'web'): int
    {
        $p = $this->process(['pdfinfo', $absPdf], (float) config('ai.pdf.info_timeout'), sys_get_temp_dir(), $profile);
        if (! $this->run($p) || $p->getExitCode() !== 0) {
            return 0;
        }

        return preg_match('/^Pages:\s+(\d+)\s*$/m', $p->getOutput(), $m) === 1 ? (int) $m[1] : 0;
    }

    /**
     * One page (1-based) as JPEG bytes, or null. A single pdftoppm spawn and no pdfinfo: a page past the end makes
     * pdftoppm exit non-zero without writing a file, which is the same null.
     */
    public function page(string $absPdf, int $page): ?string
    {
        if ($page < 1) {
            return null;
        }

        $dir = WorkDir::makeTempDir();
        try {
            $base = $dir.'/p';
            $p = $this->process(
                ['pdftoppm', '-f', (string) $page, '-l', (string) $page, '-singlefile', '-jpeg', '-jpegopt', 'quality=82',
                    '-scale-to', (string) (int) config('ai.pdf.scale'), $absPdf, $base],
                (float) config('ai.pdf.timeout'),
                $dir,
            );
            if (! $this->run($p) || $p->getExitCode() !== 0 || ! is_file($base.'.jpg')) {
                return null;
            }
            $bytes = file_get_contents($base.'.jpg');

            return $bytes === false || $bytes === '' ? null : $bytes;
        } finally {
            WorkDir::removeTree($dir);
        }
    }

    /**
     * Writes page-1.jpg .. page-k.jpg (k = min(total, max)) into $dir.
     *
     * @return array{written: list<string>, total: int}
     */
    public function pages(string $absPdf, string $dir, int $max): array
    {
        $total = $this->pageCount($absPdf, 'worker');
        $k = min($total, $max);
        $written = [];
        if ($k < 1) {
            return ['written' => [], 'total' => $total];
        }

        $tmp = WorkDir::makeTempDir();
        try {
            $p = $this->process(
                ['pdftoppm', '-f', '1', '-l', (string) $k, '-jpeg', '-jpegopt', 'quality=82',
                    '-scale-to', (string) (int) config('ai.pdf.scale'), $absPdf, $tmp.'/p'],
                (float) config('ai.pdf.timeout'),
                $tmp,
                'worker',
            );
            if (! $this->run($p) || $p->getExitCode() !== 0) {
                return ['written' => [], 'total' => $total];
            }
            for ($i = 1; $i <= $k; $i++) {
                $src = glob($tmp.'/p-*'.$i.'.jpg');
                $src = $src === false ? [] : array_values(array_filter(
                    $src,
                    fn (string $f): bool => (int) preg_replace('/\D/', '', basename($f)) === $i,
                ));
                if ($src === [] || ! @rename($src[0], $dir.'/page-'.$i.'.jpg')) {
                    foreach ($written as $w) {
                        @unlink($w);
                    }

                    return ['written' => [], 'total' => $total];
                }
                $written[] = $dir.'/page-'.$i.'.jpg';
            }
        } finally {
            WorkDir::removeTree($tmp);
        }

        return ['written' => $written, 'total' => $total];
    }

    /**
     * @param  list<string>  $command
     */
    private function process(array $command, float $timeout, string $cwd, string $profile = 'web'): Process
    {
        // Virtual address space, kept below the container's memory limit so a hostile PDF dies in the tool, not in the cgroup.
        $kb = (int) config($profile === 'worker' ? 'ai.pdf.ulimit_kb_worker' : 'ai.pdf.ulimit_kb');
        $p = new Process(['sh', '-c', 'ulimit -v '.$kb.'; exec "$@"', 'sh', ...$command], $cwd);
        $p->setTimeout($timeout);

        return $p;
    }

    /** Runs to completion; false on timeout (the child is killed). Output is discarded after the call. */
    private function run(Process $p): bool
    {
        try {
            $p->run();
        } catch (ProcessTimedOutException) {
            $p->stop(0, SIGKILL);

            return false;
        }

        return true;
    }
}
